'use strict';
const KAINCHECK_INSTALL_URL='https://kaincheck-mobile-demo-ginoki.snowydrake.chatgpt.site/';
let kaincheckInstallPrompt=null,kaincheckWorkerReady=false;
function isKaincheckInstalled(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;}
function kaincheckInstallButton(){return isKaincheckInstalled()?'':`<button class="install-icon" data-action="install-app" aria-label="Install KainCheck">${ic('install')}</button>`;}
function installKaincheckGuide(){const installed=isKaincheckInstalled(),ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),android=/Android/.test(navigator.userAgent);showModal(installed?'KainCheck is installed':'Install KainCheck',`<div class="install-app-intro"><img src="icons/icon-192.png" width="60" height="60" alt="KainCheck app icon"><div><h3>KainCheck</h3><p>Your food, plans and coach.<br>One tap from your Home Screen.</p></div></div>${installed?'<div class="notice">You’re using the installed app. Food logging and the sample demo work offline after the app has loaded. Live AI needs internet.</div>':`${kaincheckInstallPrompt?'<button class="primary" data-action="prompt-install-app">Install app</button>':''}<div class="install-phone-tabs" role="group" aria-label="Phone installation guide"><button data-action="install-guide-android" class="${!ios?'selected':''}" aria-pressed="${!ios}">Android</button><button data-action="install-guide-ios" class="${ios?'selected':''}" aria-pressed="${ios}">iPhone</button></div><div id="install-phone-steps">${installPhoneSteps(ios?'ios':'android')}</div>${!android&&!ios?'<div class="install-qr"><img src="install-qr.png" width="192" height="192" alt="QR code to open KainCheck on your phone"><p>Scan with your phone’s camera.</p></div>':''}<a class="secondary install-open-link" href="${KAINCHECK_INSTALL_URL}" target="_blank" rel="noopener">Open the phone installation link ${ic('arrow')}</a><button class="text-btn" data-action="copy-install-link">Copy app link</button><p class="install-access-note">If asked, sign in with the same account you use for this private demo. Keep the app open online once to prepare offline access. Live AI still needs internet.</p>`}<div class="save-bar"><button class="primary" data-action="close">${installed?'Continue':'Done'}</button></div>`);}
function installPhoneSteps(platform){return platform==='ios'?`<ol class="install-steps"><li>Open the app link in <strong>Safari</strong> on your iPhone.</li><li>Open <strong>Share</strong>, then choose <strong>Add to Home Screen</strong>.</li><li>Turn on <strong>Open as Web App</strong> if shown, then tap <strong>Add</strong>.</li><li>Launch <strong>KainCheck</strong> from its new Home Screen icon.</li></ol>`:`<ol class="install-steps"><li>Open the app link in <strong>Chrome</strong> on your Android phone.</li><li>Open the <strong>⋮ menu</strong>, then choose <strong>Install app</strong> or <strong>Install and create shortcut</strong>.</li><li>If shown, choose <strong>Install</strong> and confirm.</li><li>Launch <strong>KainCheck</strong> from its new app icon.</li></ol>`;}
async function promptKaincheckInstall(){if(!kaincheckInstallPrompt){installKaincheckGuide();return;}const prompt=kaincheckInstallPrompt;kaincheckInstallPrompt=null;try{await prompt.prompt();const result=await prompt.userChoice;if(result.outcome==='accepted'){closeModal();toast('Follow your phone’s installation prompt.');}else installKaincheckGuide();}catch{installKaincheckGuide();}}
function switchInstallGuide(platform){$('#install-phone-steps').innerHTML=installPhoneSteps(platform);for(const b of document.querySelectorAll('.install-phone-tabs button')){const selected=b.dataset.action==='install-guide-'+platform;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));}}
async function copyKaincheckInstallLink(){try{await navigator.clipboard.writeText(KAINCHECK_INSTALL_URL);toast('App link copied. Open it on your phone.');}catch{showModal('Open this link on your phone',`<label class="field"><span>KainCheck app link</span><input value="${KAINCHECK_INSTALL_URL}" readonly onfocus="this.select()"></label><a class="primary" href="${KAINCHECK_INSTALL_URL}" target="_blank" rel="noopener">Open KainCheck</a>`);}}
function installKaincheckPwa(){iconPaths.install='<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>';Object.assign(actions,{'install-app':installKaincheckGuide,'prompt-install-app':promptKaincheckInstall,'install-guide-android':()=>switchInstallGuide('android'),'install-guide-ios':()=>switchInstallGuide('ios'),'copy-install-link':copyKaincheckInstallLink});
 if('serviceWorker' in navigator&&['https:','http:'].includes(location.protocol)&&window.isSecureContext){window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'}).then(()=>navigator.serviceWorker.ready).then(()=>{kaincheckWorkerReady=true;}).catch(()=>{kaincheckWorkerReady=false;});});}
}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();kaincheckInstallPrompt=e;});
window.addEventListener('appinstalled',()=>{kaincheckInstallPrompt=null;closeModal();render(true);toast('KainCheck added to your apps.');});
